    TestCase(
      testId: 'GY.SL.DLE.VAL.1',
      testCasesName: 'Steady State Cornering – Constant Radius – Left – 0.3 g – Driver Only',
      tireType: '', tireCondition: 'New',
      tirePressure: 'Standard pressure±0.5', roadSurface: 'Dry Asphalt',
      load: 'Driver Only',
      testDescription: 'Test Procedure: (Steady State Cornering – Load Variation) 1. Set the vehicle to the Driver only condition; secure the load and record the actual mass and front / rear axle distribution on calibrated scales. 2. Set tire pressure to placard (nominal) and confirm all logger channels are recording. 3. Enter the constant-radius circular track turning left. 4. Increase speed slowly and hold a steady state at 0.3 g lateral acceleration for a minimum of 3 complete laps (at least 10 s of stabilised data per lap). 5. Hold steering, throttle and speed as steady as possible; log lateral acceleration, steering angle, wheel speeds, yaw rate and the DLE estimated load. 6. Expected Result: Estimated load matches the actual measured load within the specified tolerance and remains stable throughout the steady state phase.',
      testCaseLink: '', testResult: '', comments: 'Record actual total mass and axle loads. Lateral acceleration target 0.3 g.',
      feature: 'DLE', activityType: 'Validation', drivetrain: 'Both',
      waterDepth: 'N/A', loadCategory: 'Driver Only', roadSurfaceType: 'Dry',
    ),
